import * as THREE from 'three';
import { createScene } from './object.js';
import * as fs from 'fs';
import * as path from 'path';

// Create the scene
const root = createScene();

// Apply -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
const rotationMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

// Helper function to apply world matrix and rotation to get final vertex positions
function getWorldVertices(mesh, parentMatrix) {
  const geometry = mesh.geometry;
  const position = geometry.getAttribute('position');
  const vertices = [];

  // Compute the full world matrix for this mesh
  mesh.updateMatrix();
  const worldMatrix = new THREE.Matrix4().multiplyMatrices(parentMatrix, mesh.matrix);

  // Apply the Z-up rotation
  const finalMatrix = new THREE.Matrix4().multiplyMatrices(rotationMatrix, worldMatrix);

  for (let i = 0; i < position.count; i++) {
    const vertex = new THREE.Vector3(
      position.getX(i),
      position.getY(i),
      position.getZ(i)
    );
    vertex.applyMatrix4(finalMatrix);
    vertices.push(vertex);
  }

  return vertices;
}

// Helper function to get faces from geometry
function getFaces(geometry) {
  const faces = [];
  const index = geometry.getIndex();

  if (index) {
    for (let i = 0; i < index.count; i += 3) {
      faces.push([index.getX(i), index.getX(i + 1), index.getX(i + 2)]);
    }
  } else {
    const position = geometry.getAttribute('position');
    for (let i = 0; i < position.count; i += 3) {
      faces.push([i, i + 1, i + 2]);
    }
  }

  return faces;
}

// Collect all meshes with their world transforms
const meshData = [];

function collectMeshes(object, parentMatrix) {
  object.updateMatrix();
  const worldMatrix = new THREE.Matrix4().multiplyMatrices(parentMatrix, object.matrix);

  if (object.isMesh) {
    if (object.isInstancedMesh) {
      // Handle InstancedMesh - each instance has its own transform
      const instanceMatrix = new THREE.Matrix4();
      for (let i = 0; i < object.count; i++) {
        object.getMatrixAt(i, instanceMatrix);
        const instanceWorldMatrix = new THREE.Matrix4().multiplyMatrices(worldMatrix, instanceMatrix);
        meshData.push({
          geometry: object.geometry,
          worldMatrix: instanceWorldMatrix,
          name: `${object.name || 'mesh'}_instance_${i}`
        });
      }
    } else {
      meshData.push({
        geometry: object.geometry,
        worldMatrix: worldMatrix,
        name: object.name || 'mesh'
      });
    }
  }

  for (const child of object.children) {
    collectMeshes(child, worldMatrix);
  }
}

// Start collecting from root with identity matrix
const identityMatrix = new THREE.Matrix4();
collectMeshes(root, identityMatrix);

// Generate OBJ content
let objContent = '# OBJ file exported from Three.js\n';
objContent += '# Converted to Blender Z-up coordinate system\n\n';

let vertexOffset = 0;

for (const data of meshData) {
  const { geometry, worldMatrix, name } = data;

  objContent += `o ${name}\n`;

  // Get position attribute
  const position = geometry.getAttribute('position');

  // Apply the Z-up rotation combined with world matrix
  const finalMatrix = new THREE.Matrix4().multiplyMatrices(rotationMatrix, worldMatrix);

  // Write vertices
  for (let i = 0; i < position.count; i++) {
    const vertex = new THREE.Vector3(
      position.getX(i),
      position.getY(i),
      position.getZ(i)
    );
    vertex.applyMatrix4(finalMatrix);
    objContent += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
  }

  // Write faces
  const faces = getFaces(geometry);
  for (const face of faces) {
    // OBJ indices are 1-based
    const i1 = face[0] + 1 + vertexOffset;
    const i2 = face[1] + 1 + vertexOffset;
    const i3 = face[2] + 1 + vertexOffset;
    objContent += `f ${i1} ${i2} ${i3}\n`;
  }

  vertexOffset += position.count;
  objContent += '\n';
}

// Write to file
const outputPath = '/root/output/object.obj';
fs.writeFileSync(outputPath, objContent);
console.log(`Successfully exported to ${outputPath}`);
console.log(`Total meshes exported: ${meshData.length}`);

